// Una "API de biblioteca": las funciones que el módulo deja a la vista
const envios = new Map([
  ["AR-1001", { estado: "en_ruta", ubicacion: "Depósito Pompeya" }],
  ["AR-1002", { estado: "entregado", ubicacion: "Cliente" }],
]);

function estadoEnvio(id) {            // parte del contrato: nombre, argumento, resultado
  const e = envios.get(id);
  if (!e) throw new Error("envio_inexistente");   // parte del contrato: cómo avisa el error
  return { id, estado: e.estado, ubicacion: e.ubicacion }; // una copia, no el objeto interno
}

console.log(estadoEnvio("AR-1001"));
try { estadoEnvio("AR-9999"); } catch (e) { console.log("error:", e.message); }

// El llamador toca lo que recibió: como es una copia, los datos del dueño no cambian
const copia = estadoEnvio("AR-1001");
copia.estado = "perdido";
console.log("después de tocar la copia:", estadoEnvio("AR-1001").estado);

import http from "node:http";
import { estadoEnvio } from "./seguimiento.mjs";   // la misma función de antes

http.createServer((req, res) => {
  const m = req.method === "GET" && req.url.match(/^\/envios\/([A-Z0-9-]+)$/);
  if (!m) { res.writeHead(404); return res.end(JSON.stringify({ error: "ruta_inexistente" })); }
  try {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify(estadoEnvio(m[1])));
  } catch (err) {
    res.writeHead(404, { "content-type": "application/json" });
    res.end(JSON.stringify({ error: err.message }));
  }
}).listen(20801, "127.0.0.1");
